/* Browser-local optional widgets. No OS, network, geolocation or media adapters. */
(()=>{'use strict';
const reviewWidgets=new URLSearchParams(location.search).get('review')==='1';
const storeKey='atmos-optional-widgets-v1',scene=document.getElementById('scene');let stage=scene,autoPlan=null;
const specs={weather:{name:'天氣',size:[224,145]},todo:{name:'待辦',size:[280,190]},timer:{name:'番茄鐘',size:[224,174]},system:{name:'系統資訊',size:[280,178]},media:{name:'Now Playing',size:[280,142]}};
const initial=()=>({schema:1,desktopZone:null,cards:Object.fromEntries(Object.keys(specs).map((id,i)=>[id,{enabled:false,size:'S',custom:false,mobileCustom:false,x:4+(i%3)*28,y:55+(i>2?15:0),mx:5,my:12+i*12}])),todos:[],undo:null,city:'台北',weatherState:'demo',systemState:'unavailable',mediaState:'empty',metrics:{cpu:true,ram:true,up:true,down:true},timer:{phase:'work',minutes:25,running:false,deadlineUtc:0,pausedRemaining:1500000,finished:false}});
let data=initial(),editing=false,active=null,warning='',pageIndex=0;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function timerProjection(t,now){if(!t.running)return {remaining:Math.max(0,t.pausedRemaining),ended:false};return {remaining:Math.max(0,t.deadlineUtc-now),ended:now>=t.deadlineUtc}}
function clampPoint(x,y,w,h,cw,ch){return {x:Math.max(8,Math.min(Math.max(8,cw-w-8),x)),y:Math.max(8,Math.min(Math.max(8,ch-h-8),y))}}
function sanitize(raw){const d=initial();if(!raw||raw.schema!==1)return d;if(['scene','tray'].includes(raw.desktopZone))d.desktopZone=raw.desktopZone;for(const id of Object.keys(specs)){const c=raw.cards?.[id];if(!c)continue;d.cards[id].enabled=c.enabled===true;d.cards[id].custom=c.custom===true;d.cards[id].mobileCustom=c.mobileCustom===true;d.cards[id].size=c.size==='M'?'M':'S';for(const k of ['x','y','mx','my'])if(Number.isFinite(c[k]))d.cards[id][k]=Math.max(0,Math.min(100,c[k]))}d.todos=Array.isArray(raw.todos)?raw.todos.filter(t=>t&&typeof t.text==='string').slice(0,50).map((t,i)=>({id:String(t.id||i).slice(0,80),text:t.text.slice(0,160),done:t.done===true})):[];if(['台北','東京','倫敦','紐約'].includes(raw.city))d.city=raw.city;for(const [k,choices] of [['weatherState',['demo','denied','offline','empty']],['systemState',['demo','unavailable']],['mediaState',['demo','empty']]])if(choices.includes(raw[k]))d[k]=raw[k];if(raw.metrics){for(const k of Object.keys(d.metrics))if(typeof raw.metrics[k]==='boolean')d.metrics[k]=raw.metrics[k];if(!Object.values(d.metrics).some(Boolean))d.metrics.cpu=true}const t=raw.timer;if(t){d.timer.phase=t.phase==='break'?'break':'work';d.timer.minutes=Number.isFinite(t.minutes)?Math.max(1,Math.min(120,t.minutes)):25;d.timer.pausedRemaining=Number.isFinite(t.pausedRemaining)?Math.max(0,Math.min(7200000,t.pausedRemaining)):d.timer.minutes*60000;d.timer.deadlineUtc=Number.isFinite(t.deadlineUtc)?t.deadlineUtc:0;d.timer.running=t.running===true&&d.timer.deadlineUtc>0;d.timer.finished=t.finished===true}return d}
try{const raw=reviewWidgets?null:localStorage.getItem(storeKey);if(raw)data=sanitize(JSON.parse(raw))}catch(e){warning='設定無法讀取，元件回到安全預設。'}
function save(){if(reviewWidgets){status();return}try{localStorage.setItem(storeKey,JSON.stringify(data));warning=''}catch(e){warning='未能儲存：目前變更只在本頁，關閉後可能遺失。'}status()}
const mobileHost=document.createElement('div');mobileHost.className='widget-mobile-host';mobileHost.hidden=true;mobileHost.setAttribute('aria-label','可選元件區');scene.insertAdjacentElement('afterend',mobileHost);
const layer=document.createElement('div');layer.className='widget-layer';scene.append(layer);
const manager=document.createElement('dialog');manager.id='widgetManager';manager.setAttribute('aria-labelledby','widgetManagerTitle');document.body.append(manager);
const openButton=document.createElement('button');openButton.type='button';openButton.id='openWidgetManager';openButton.className='widget-manage-button';openButton.textContent='元件管理';document.getElementById('themeSettings').append(openButton);
manager.innerHTML=`<div class="manager-top"><h2 id="widgetManagerTitle">元件管理</h2><button id="closeWidgetManager" type="button">關閉</button></div><p>預設關閉；開關保留位置與內容。桌面預設避開時鐘與日曆，放不下時另列於主景下方；窄屏在主景下方逐張切換；整理位置會還原各卡預設位置；改尺寸或視窗後若重疊，請用整理或手動調整，不會偷偷重排你的配置。僅瀏覽器 prototype，沒有接入桌面穿透或真資料服務。</p><div class="config-row"><label><input id="editWidgets" type="checkbox">編輯位置（拖曳／方向鍵，Esc 取消拖動）</label><button id="hideAllWidgets" type="button">全部隱藏</button><button id="arrangeWidgets" type="button">整理位置</button></div><p id="widgetSaveStatus" class="manager-status" role="status"></p><div id="widgetConfigList"></div><div class="widget-config"><h3>天氣 · 示範資料</h3><div class="config-row"><label>城市<select id="widgetCity"><option>台北</option><option>東京</option><option>倫敦</option><option>紐約</option></select></label><label>資料情境<select id="weatherScenario"><option value="demo">示範晴天</option><option value="offline">離線／過期快取</option><option value="empty">無資料</option><option value="denied">定位被拒絕</option></select></label><button id="demoLocate" type="button">模擬定位失敗</button></div><p class="widget-help">不會讀取你的位置或 IP；失敗後仍可手選城市。真天氣服務未接。</p></div><div class="widget-config"><h3>待辦 · 僅此瀏覽器儲存</h3><form id="todoForm" class="todo-editor-row"><input id="todoInput" type="text" maxlength="160" placeholder="新增待辦" aria-label="新增待辦" required><button type="submit">新增</button></form><div id="todoEditor"></div><button id="undoTodo" type="button">復原刪除</button></div><div class="widget-config"><h3>番茄鐘 · 本機計時</h3><div class="config-row"><label>階段<select id="timerPhase"><option value="work">工作</option><option value="break">休息</option></select></label><label>分鐘<input id="timerMinutes" class="timer-input" type="number" min="1" max="120" step="1"></label></div><p id="timerManagerStatus"></p><div class="config-row"><button data-timer-action="toggle">開始／暫停／繼續</button><button data-timer-action="reset">重設</button></div><p class="widget-help">隱藏仍繼續計時，重開以結束時間重算；離開期間逾時只結算一次，不自動進下一輪。不保證背景響鈴或 OS 通知。</p></div><div class="widget-config"><h3>系統資訊 · 真 host 未接</h3><label>情境<select id="systemScenario"><option value="unavailable">未收到資料 · N/A</option><option value="demo">固定示範樣本</option></select></label><div class="config-row" id="metricToggles"></div><p class="widget-help">上下行是流量，不是測速。電量待實機核實，永遠顯示 N/A，不假造100%。</p></div><div class="widget-config"><h3>Now Playing · 只讀展示</h3><select id="mediaScenario"><option value="empty">未收到播放資訊</option><option value="demo">虛構示範曲目</option></select><p class="widget-help">沒有讀取媒體、攔廣告或播放／跳歌控制。</p></div>`;
const q=id=>document.getElementById(id);q('widgetConfigList').innerHTML=Object.entries(specs).map(([id,s])=>`<div class="widget-config config-row"><label><input type="checkbox" data-widget-enable="${id}">${s.name}</label><label>尺寸<select data-widget-size="${id}" aria-label="${s.name}尺寸"><option value="S">S</option><option value="M">M</option></select></label></div>`).join('');q('metricToggles').innerHTML=Object.entries({cpu:'CPU',ram:'RAM',up:'上傳',down:'下載'}).map(([id,label])=>`<label><input type="checkbox" data-metric="${id}">${label}</label>`).join('');
function status(){q('widgetSaveStatus').textContent=warning||'資料只儲存在此瀏覽器，未外部同步。'}
function formatTime(ms){const secs=Math.ceil(ms/1000);return String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0')}
function timerStateText(){const t=data.timer;return (t.phase==='work'?'工作':'休息')+' '+formatTime(timerProjection(t,Date.now()).remaining)+(t.finished?' · 已結束，請手動開始下一段':t.running?' · 計時中':' · 已暫停')}
function updateTimer(){const p=timerProjection(data.timer,Date.now());if(p.ended){data.timer.running=false;data.timer.pausedRemaining=0;data.timer.finished=true;save()}const text=timerStateText();q('timerManagerStatus').textContent=text;const e=layer.querySelector('[data-timer-value]');if(e)e.textContent=formatTime(p.remaining);const note=layer.querySelector('[data-timer-note]');if(note)note.textContent=data.timer.finished?'離開期間或本次計時已結束':data.timer.running?'計時中':'已暫停';const b=layer.querySelector('[data-timer-action=toggle]');if(b)b.textContent=data.timer.running?'暫停':data.timer.finished?'再開始':'開始／繼續'}
function syncManager(){for(const e of manager.querySelectorAll('[data-widget-enable]'))e.checked=data.cards[e.dataset.widgetEnable].enabled;for(const e of manager.querySelectorAll('[data-widget-size]'))e.value=data.cards[e.dataset.widgetSize].size;for(const e of manager.querySelectorAll('[data-metric]'))e.checked=data.metrics[e.dataset.metric];q('editWidgets').checked=editing;q('widgetCity').value=data.city;q('weatherScenario').value=data.weatherState;q('systemScenario').value=data.systemState;q('mediaScenario').value=data.mediaState;q('timerPhase').value=data.timer.phase;q('timerMinutes').value=data.timer.minutes;q('todoEditor').innerHTML=data.todos.length?data.todos.map(t=>`<div class="todo-editor-row"><input type="checkbox" data-todo-toggle="${esc(t.id)}" ${t.done?'checked':''} aria-label="完成 ${esc(t.text)}"><span>${esc(t.text)}</span><button data-todo-delete="${esc(t.id)}">刪除</button></div>`).join(''):'<p>尚無待辦。</p>';q('undoTodo').disabled=!data.undo;status();updateTimer()}
function bodyFor(id){if(id==='weather'){const missing=['denied','empty'].includes(data.weatherState);return `<div class="widget-big">${missing?'—':'24°'}</div><p>${esc(data.city)} · ${missing?'無天氣資料':'晴朗 · 示範'}</p><small>${data.weatherState==='denied'?'模擬定位失敗，可在管理面板手選':data.weatherState==='offline'?'離線：示範快取已過期，非目前天氣':missing?'真服務未接':'固定合成樣本，非即時觀測'}</small>`}if(id==='todo'){const items=data.todos.slice(0,3);return (items.length?items.map(t=>`<label class="widget-todo-item"><input type="checkbox" data-todo-toggle="${esc(t.id)}" ${t.done?'checked':''}><span>${esc(t.text)}</span></label>`).join(''):'<p>尚無待辦</p>')+`<small>${data.todos.length>3?'還有 '+(data.todos.length-3)+' 項 · ':''}僅此瀏覽器</small><div><button data-open-manager>管理待辦</button></div>`}if(id==='timer')return `<div class="widget-big" data-timer-value></div><small data-timer-note></small><div class="widget-actions"><button data-timer-action="toggle">開始</button><button data-timer-action="reset">重設</button></div>`;if(id==='system'){const demo=data.systemState==='demo';const vals={cpu:['CPU',demo?'18%':'N/A'],ram:['RAM',demo?'6.4 GB':'N/A'],up:['上傳',demo?'0 KB/s':'N/A'],down:['下載',demo?'128 KB/s':'N/A']};return '<div class="widget-metrics">'+Object.entries(vals).filter(([k])=>data.metrics[k]).map(([,v])=>`<div>${v[0]}<b>${v[1]}</b></div>`).join('')+'</div><small>電量 N/A · '+(demo?'合成固定樣本／虛構網卡':'未收到 host 資料')+'</small>'}return data.mediaState==='demo'?'<p><b>晨光散步</b></p><p>虛構音樂人 · 示範播放器</p><small>合成 metadata，非真實播放</small>':'<p>未收到播放資訊</p><small>未接媒體來源，不代表其他 App 沒播放</small>'}
function keys(){return matchMedia('(max-width:600px)').matches?['mx','my']:['x','y']}
function dimensions(id){const c=data.cards[id],s=specs[id],scale=c.size==='M'?1.18:1;return {w:Math.min(s.size[0]*scale,stage.clientWidth-16),h:Math.min(s.size[1]*scale,stage.clientHeight-16)}}
function packRectangles(items,width,height,obstacles=[]){const occupied=obstacles.map(o=>({...o})),points={};for(const item of items){let found=null;for(let y=8;y+item.h<=height-8&&!found;y+=8)for(let x=8;x+item.w<=width-8;x+=8){if(occupied.every(o=>x+item.w+8<=o.x||o.x+o.w+8<=x||y+item.h+8<=o.y||o.y+o.h+8<=y)){found={x,y,w:item.w,h:item.h};break}}if(!found)return null;points[item.id]=found;occupied.push(found)}return points}
function gridPoint(id){const ids=Object.keys(specs),maxWidth=Math.max(...ids.map(k=>dimensions(k).w)),cols=Math.max(1,Math.min(3,Math.floor((stage.clientWidth-4)/(maxWidth+12)))),rows=[];for(let i=0;i<ids.length;i+=cols)rows.push(Math.max(...ids.slice(i,i+cols).map(k=>dimensions(k).h)));const index=ids.indexOf(id),row=Math.floor(index/cols);return {x:8+(index%cols)*(maxWidth+12),y:48+rows.slice(0,row).reduce((a,b)=>a+b+12,0)}}
function prepareStage(enabled){const mobile=matchMedia('(max-width:600px)').matches;stage=scene;autoPlan=null;const fresh=data.desktopZone===null;let fallback=data.desktopZone==='tray';if(!mobile&&enabled.length&&fresh){const r=scene.getBoundingClientRect(),sx=scene.clientWidth/r.width,sy=scene.clientHeight/r.height,obstacles=['clock','calendar'].map(id=>document.getElementById(id)).filter(e=>getComputedStyle(e).display!=='none').map(e=>{const b=e.getBoundingClientRect();return {x:(b.left-r.left)*sx,y:(b.top-r.top)*sy,w:b.width*sx,h:b.height*sy}});autoPlan=packRectangles(Object.keys(specs).map(id=>({id,...dimensions(id)})),scene.clientWidth,scene.clientHeight,obstacles);fallback=!autoPlan;data.desktopZone=fallback?'tray':'scene';if(autoPlan)for(const [id,p] of Object.entries(autoPlan)){data.cards[id].x=p.x/scene.clientWidth*100;data.cards[id].y=p.y/scene.clientHeight*100;data.cards[id].custom=true}}if((mobile||fallback)&&enabled.length){mobileHost.hidden=false;mobileHost.style.height=(Math.max(...Object.keys(specs).map(id=>specs[id].size[1]*(data.cards[id].size==='M'?1.18:1)))+64)+'px';stage=mobileHost;layer.parentNode!==mobileHost&&mobileHost.append(layer);const heights=Object.keys(specs).map(id=>dimensions(id).h);if(mobile)mobileHost.style.height=(Math.max(...heights)+64)+'px';else{const maxWidth=Math.max(...Object.keys(specs).map(id=>dimensions(id).w)),cols=Math.max(1,Math.min(3,Math.floor((stage.clientWidth-4)/(maxWidth+12)))),rows=[];for(let i=0;i<heights.length;i+=cols)rows.push(Math.max(...heights.slice(i,i+cols)));mobileHost.style.height=(rows.reduce((a,b)=>a+b,0)+rows.length*12+52)+'px'}mobileHost.dataset.mode=mobile?'mobile':'overflow';if(!mobile&&fresh)for(const id of Object.keys(specs)){const p=gridPoint(id);data.cards[id].x=p.x/stage.clientWidth*100;data.cards[id].y=p.y/stage.clientHeight*100;data.cards[id].custom=true}}else{mobileHost.hidden=true;layer.parentNode!==scene&&scene.append(layer)}}
function autoPoint(id){const size=dimensions(id);if(matchMedia('(max-width:600px)').matches)return {x:(stage.clientWidth-size.w)/2,y:48};return autoPlan?.[id]||gridPoint(id)}

function place(id,el){const c=data.cards[id],{w,h}=dimensions(id);el.style.width=w+'px';el.style.height=h+'px';const [kx,ky]=keys(),custom=kx==='mx'?c.mobileCustom:c.custom,base=custom?{x:c[kx]/100*stage.clientWidth,y:c[ky]/100*stage.clientHeight}:autoPoint(id),p=clampPoint(base.x,base.y,w,h,stage.clientWidth,stage.clientHeight);el.style.left=p.x+'px';el.style.top=p.y+'px';c[kx]=p.x/stage.clientWidth*100;c[ky]=p.y/stage.clientHeight*100;c[kx==='mx'?'mobileCustom':'custom']=true}

function renderCards(){layer.classList.toggle('widgets-editing',editing);const enabled=Object.keys(specs).filter(id=>data.cards[id].enabled);prepareStage(enabled);const mobile=matchMedia('(max-width:600px)').matches;pageIndex=Math.max(0,Math.min(pageIndex,enabled.length-1));const pager=mobile&&enabled.length?`<nav class="widget-pager" aria-label="窄屏元件切換"><button data-widget-page="-1" aria-label="上一個元件">‹</button><span>元件 ${pageIndex+1}/${enabled.length} · ${specs[enabled[pageIndex]].name}</span><button data-widget-page="1" aria-label="下一個元件">›</button></nav>`:(stage!==scene&&enabled.length?'<div class="widget-tray-label">可選元件 · 主景空間不足，移至獨立區避免遮擋</div>':'');layer.innerHTML=pager+Object.entries(specs).filter(([id])=>data.cards[id].enabled&&(!mobile||id===enabled[pageIndex])).map(([id,s])=>`<section class="wall-widget" data-widget="${id}" aria-label="${s.name}元件"><header><b>${s.name}</b><span class="widget-badge">${['todo','timer'].includes(id)?'本機':'示範／未連線'}</span></header><button class="widget-drag" data-widget-drag="${id}" aria-label="拖曳${s.name}位置">↕ ${s.name} · 拖曳／方向鍵</button><div class="widget-body">${bodyFor(id)}</div></section>`).join('');for(const el of layer.querySelectorAll('.wall-widget'))place(el.dataset.widget,el);updateTimer()}
function showManager(){syncManager();if(!manager.open)manager.showModal()}
openButton.onclick=showManager;q('closeWidgetManager').onclick=()=>manager.close();q('editWidgets').onchange=e=>{editing=e.target.checked;renderCards();manager.close();if(editing)layer.querySelector('.widget-drag')?.focus()};q('arrangeWidgets').onclick=()=>{data.desktopZone=null;for(const c of Object.values(data.cards)){c.custom=false;c.mobileCustom=false}renderCards();save();syncManager()};q('hideAllWidgets').onclick=()=>{for(const c of Object.values(data.cards))c.enabled=false;renderCards();save();syncManager()};
manager.addEventListener('change',e=>{const el=e.target;if(el.dataset.widgetEnable){data.cards[el.dataset.widgetEnable].enabled=el.checked;if(el.checked)pageIndex=Object.keys(specs).filter(id=>data.cards[id].enabled).indexOf(el.dataset.widgetEnable);renderCards()}if(el.dataset.widgetSize){data.cards[el.dataset.widgetSize].size=el.value;renderCards()}if(el.dataset.metric){data.metrics[el.dataset.metric]=el.checked;if(!Object.values(data.metrics).some(Boolean)){data.metrics[el.dataset.metric]=true;el.checked=true}renderCards()}save()});
for(const [id,key] of [['widgetCity','city'],['weatherScenario','weatherState'],['systemScenario','systemState'],['mediaScenario','mediaState']])q(id).onchange=e=>{data[key]=e.target.value;if(id==='widgetCity'&&data.weatherState==='denied')data.weatherState='demo';renderCards();save();syncManager()};q('demoLocate').onclick=()=>{data.weatherState='denied';renderCards();save();syncManager()};
q('todoForm').onsubmit=e=>{e.preventDefault();const input=q('todoInput'),text=input.value.trim();if(!text||data.todos.length>=50)return;data.todos.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),text,done:false});input.value='';renderCards();save();syncManager()};q('undoTodo').onclick=()=>{if(data.undo&&data.todos.length<50){data.todos.splice(Math.min(data.undo.index,data.todos.length),0,data.undo.item);data.undo=null;renderCards();save();syncManager()}};
function timerAction(action){const t=data.timer;if(action==='reset'){t.running=false;t.finished=false;t.pausedRemaining=t.minutes*60000;t.deadlineUtc=0}else if(t.running){t.pausedRemaining=timerProjection(t,Date.now()).remaining;t.running=false}else{if(t.pausedRemaining<=0)t.pausedRemaining=t.minutes*60000;t.finished=false;t.deadlineUtc=Date.now()+t.pausedRemaining;t.running=true}save();updateTimer()}
q('timerPhase').onchange=e=>{data.timer.phase=e.target.value;data.timer.minutes=e.target.value==='break'?5:25;timerAction('reset');syncManager()};q('timerMinutes').onchange=e=>{data.timer.minutes=Math.max(1,Math.min(120,Math.round(Number(e.target.value)||25)));timerAction('reset');syncManager()};
function actions(e){const el=e.target.closest('button,input');if(!el)return;if(el.dataset.widgetPage){const ids=Object.keys(specs).filter(id=>data.cards[id].enabled);pageIndex=(pageIndex+Number(el.dataset.widgetPage)+ids.length)%ids.length;renderCards();return}if(el.dataset.timerAction)timerAction(el.dataset.timerAction);if(el.hasAttribute('data-open-manager'))showManager();if(el.dataset.todoToggle){const t=data.todos.find(t=>t.id===el.dataset.todoToggle);if(t)t.done=el.checked;renderCards();save();syncManager()}if(el.dataset.todoDelete){const i=data.todos.findIndex(t=>t.id===el.dataset.todoDelete);if(i>=0){data.undo={index:i,item:data.todos[i]};data.todos.splice(i,1);renderCards();save();syncManager()}}}manager.addEventListener('click',actions);layer.addEventListener('click',actions);
function move(id,dx,dy){const c=data.cards[id],[kx,ky]=keys();c[kx==='mx'?'mobileCustom':'custom']=true;c[kx]+=dx/stage.clientWidth*100;c[ky]+=dy/stage.clientHeight*100;place(id,layer.querySelector(`[data-widget="${id}"]`))}
layer.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-widget-drag]');if(!editing||!h)return;e.preventDefault();const id=h.dataset.widgetDrag;active={id,pointer:e.pointerId,start:{...data.cards[id]},x:e.clientX,y:e.clientY,handle:h};h.setPointerCapture(e.pointerId)});
layer.addEventListener('pointermove',e=>{if(!active||e.pointerId!==active.pointer)return;const r=stage.getBoundingClientRect(),sx=stage.clientWidth/r.width,sy=stage.clientHeight/r.height;move(active.id,(e.clientX-active.x)*sx,(e.clientY-active.y)*sy);active.x=e.clientX;active.y=e.clientY});
function endDrag(cancel=false){if(!active)return;const a=active;if(cancel){data.cards[a.id]=a.start;place(a.id,layer.querySelector(`[data-widget="${a.id}"]`))}try{a.handle.releasePointerCapture(a.pointer)}catch(e){}active=null;if(!cancel)save()}
layer.addEventListener('pointerup',()=>endDrag());layer.addEventListener('pointercancel',()=>endDrag(true));layer.addEventListener('keydown',e=>{const h=e.target.closest('[data-widget-drag]');if(!h)return;if(e.key==='Escape'){e.preventDefault();if(active)endDrag(true);else{editing=false;renderCards();openButton.focus()}return}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const n=e.shiftKey?16:8;move(h.dataset.widgetDrag,e.key==='ArrowLeft'?-n:e.key==='ArrowRight'?n:0,e.key==='ArrowUp'?-n:e.key==='ArrowDown'?n:0);save()}});
addEventListener('resize',()=>{if(active)endDrag(true);renderCards()});document.addEventListener('visibilitychange',updateTimer);setInterval(updateTimer,1000);syncManager();renderCards();
})();
